<template><main class="mx-auto max-w-[1500px] px-4 py-6 md:px-7 md:py-7"><AdminPurchasingWorkflow/><NuxtLink to="/admin/purchasing/purchase-orders" class="text-sm font-bold text-blue-600">← Purchase Orders</NuxtLink><div class="mt-2 flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-3xl font-black">Supplier Bills</h1><p class="text-slate-500">Manage supplier invoices created from purchase orders and post payments against them.</p></div><button class="secondary" @click="load">Refresh</button></div><div v-if="msg" class="my-4 rounded-lg bg-slate-100 p-3">{{msg}}</div><section class="panel mt-5 p-5"><div class="flex flex-wrap items-center justify-between gap-3"><h2 class="text-xl font-black">Supplier Bills</h2><NuxtLink to="/admin/accounting/payables" class="secondary">Open Accounts Payable</NuxtLink></div><div class="mt-3 overflow-x-auto"><table class="w-full min-w-[850px] text-sm"><thead><tr class="border-b text-left"><th class="p-2">Bill</th><th>Supplier</th><th>Supplier Invoice</th><th>Due</th><th>Status</th><th class="text-right">Total</th><th class="text-right">Paid</th><th class="text-right">Owing</th><th></th></tr></thead><tbody><tr v-for="b in bills" :key="b.id" class="border-b"><td class="p-2 font-bold">{{b.bill_number}}</td><td>{{b.accounting_suppliers?.name}}</td><td>{{b.supplier_invoice_number||'—'}}</td><td>{{b.due_date||'—'}}</td><td><span class="badge">{{b.status}}</span></td><td class="text-right">{{money(b.total)}}</td><td class="text-right">{{money(b.paid_amount)}}</td><td class="text-right font-bold">{{money(owing(b))}}</td><td class="text-right"><button v-if="owing(b)>0" class="primary" @click="pay(b)">Record Payment</button></td></tr><tr v-if="!bills.length"><td colspan="9" class="p-8 text-center text-slate-500">No supplier bills found.</td></tr></tbody></table></div></section></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch();const dialog=useAppDialog();const bills=ref<any[]>([]),msg=ref('');const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const owing=(b:any)=>Math.max(0,Number(b.total||0)-Number(b.paid_amount||0));async function load(){try{bills.value=await adminFetch('/api/admin/purchasing/supplier-bills')||[]}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}async function pay(b:any){const raw=await dialog.prompt(`Payment amount for ${b.bill_number}`,owing(b).toFixed(2));if(raw===null)return;const amount=Number(raw);if(!amount||amount<=0||amount>owing(b)){await dialog.alert('Enter a valid payment amount no greater than the amount owing.');return}const reference=await dialog.prompt('Payment reference','')||'';try{await adminFetch('/api/admin/accounting/supplier-payments',{method:'POST',body:{bill_id:b.id,amount,reference}});msg.value='Supplier payment posted.';await load()}catch(e:any){msg.value=e?.data?.statusMessage||e.message}}onMounted(load)</script>
<style scoped>.panel{border:1px solid #e2e8f0;border-radius:1rem;background:white}.primary,.secondary{display:inline-block;border-radius:.7rem;padding:.65rem 1rem;font-weight:800}.primary{background:#0f172a;color:white}.secondary{border:1px solid #cbd5e1;background:white}.badge{border-radius:999px;background:#f1f5f9;padding:.25rem .6rem;font-weight:700}</style>
